// The daily-life groups of posts/singapore-value-buys/post.md, which held them as tables until 11 November 2026. Official series end at September 2026. Shop prices are from 8 and 9 November 2026.
// A move is one thing to do. Its text takes Markdown links. "worth" is a figure the post already gives, and it stays empty where the post gives none.
export interface Move { lead: string; text: string; worth: string }
// Name, index in Sep 2026, change in a year, change since Sep 2015, Sep 2027 forecast, month pattern.
export type Series = readonly [string, string, string, string, string, string];
// Item, product, link, shop, price, what it covers, unit price, and 1 where the price is a search listing and not an opened page.
export type Shelf = readonly [string, string, string, string, string, string, string, number];
export interface LifeCategory { name: string; id: string; note: string; moves: readonly Move[]; series: readonly Series[]; shelf: readonly Shelf[] }

